-- 2026-10-18. Wix form labels out of imported puppy descriptions (launch workplan A10), written by
-- dev/make-wix-description-migration.mjs from the staging database. 14 descriptions started with the run of labels,
-- such as "Mom's information weight: 8 pounds color: Dad's information ...". Each keeps the breeder's own prose
-- exactly as written, the puppy's color moves to its color where that is empty, the parents' weights to the
-- litter where those are empty, and the parents' colors, which have no field, become one line for the
-- litter. Each UPDATE names the exact current description, so an edited one is left alone.

UPDATE puppies SET description = 'This is a stunning litter of Cavapoos! They have gorgeous markings, sweet expressions, and are already developing very affectionate, attentive personalities. Leash training and crate training have been started.Visit the breeder''s website to learn more and reserve your puppy!', color = COALESCE(color, 'red and white'),
  updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now'), version = version + 1
 WHERE id = 'seed-p-0021' AND description = 'Mom''s information weight: 24 pounds color: red and white Dad''s information weight: 14 pounds color: red Puppy''s color - red and white This is a stunning litter of Cavapoos! They have gorgeous markings, sweet expressions, and are already developing very affectionate, attentive personalities. Leash training and crate training have been started.Visit the breeder''s website to learn more and reserve your puppy!';
UPDATE litters SET mom_weight_lb = COALESCE(mom_weight_lb, 24), dad_weight_lb = COALESCE(dad_weight_lb, 14),
  description = CASE WHEN description IS NULL OR trim(description) = '' THEN 'Mom''s color: red and white. Dad''s color: red.' ELSE description END,
  updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now'), version = version + 1
 WHERE id = 'seed-l-peacefulpawspuppies-com-june-29-2026';
